-- Show-your-working rule for every written question that asks for working.
-- Matches questions by md5 of their text; touches only the guidance key.
update public.fm_mark_schemes m set scheme = jsonb_set(m.scheme, '{guidance}', to_jsonb($g$Accept 0.6 without the minus sign. Allow error carried forward for the elastic/inelastic judgement. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong.$g$::text))
  from public.fm_exam_questions e where e.id = m.question_id and md5(e.question_text) = 'da661a7640b1a06a06acf8ef1baabd72'; -- Price elasticity of demand
